"""Kurulum testi: modelleri indirir/yükler ve birer basit çağrı yapar.

Kullanım: python check_setup.py
"""
import sys
import time

import config
from llm import Embedder, load_model


def main():
    sys.stdout.reconfigure(encoding="utf-8")

    # 1) Embedding: Türkçe soru, ilgili İngilizce cümleyle eşleşmeli
    embedder = Embedder()
    query = "Bir container'ı nasıl başlatırım?"
    docs = [
        "Use the docker run command to create and start a new container from an image.",
        "A volume is the preferred mechanism for persisting data generated by containers.",
        "Bananas are a popular tropical fruit rich in potassium.",
    ]
    qv, *dvs = embedder.embed([query] + docs)
    print(f"Embedding ({config.EMBED_MODEL}, {len(qv)} boyut)")
    print(f"Soru: {query}")
    for doc, dv in zip(docs, dvs):
        print(f"  {sum(a * b for a, b in zip(qv, dv)):.3f}  {doc}")

    # 2) Sohbet modeli: Türkçe cevap
    chat_model = load_model(config.CHAT_MODEL)
    client = chat_model.get_chat_client()
    client.settings.temperature = config.TEMPERATURE
    client.settings.max_tokens = config.MAX_TOKENS + config.THINKING_TOKENS
    messages = [{"role": "system", "content": "Her zaman yalnızca Türkçe cevap ver."},
                {"role": "user", "content": "Docker container nedir? Kısaca açıkla."}]

    print(f"\nSohbet ({config.CHAT_MODEL})")
    start = time.perf_counter()
    text = ""
    for chunk in client.complete_streaming_chat(messages):
        if chunk.choices and chunk.choices[0].delta.content:
            text += chunk.choices[0].delta.content
    print(f"Cevap: {text.split('</think>', 1)[-1].strip()}")
    print(f"Süre: {time.perf_counter() - start:.1f} sn")

    embedder.model.unload()
    chat_model.unload()


if __name__ == "__main__":
    main()
